en = {
    GUIDE_BTN_TOOLTIP = "Forever guide (3 pages)",
    GUIDE_PAGE1_TITLE = "Getting started", GUIDE_PAGE2_TITLE = "Captures and resources",
    GUIDE_PAGE3_TITLE = "Keeps, outposts and rankings",
    GUIDE_SECTION_TRAVEL = "Enter the open world",
    GUIDE_TRAVEL_ALLIANCE = "Travel to an Overlord war front in the open world. The map shows the points you can capture, and the panel's Next Objective tells you where to go.",
    GUIDE_SECTION_RULES = "Before you capture",
    GUIDE_RULES_BODY = "Turn on PvP (/pvp) and stand inside the circle on foot. Capturing stops while you are mounted, flying, in travel form, in a vehicle or on a taxi, stealthed or dead; if you fly into a circle, you are dismounted after a short warning.",
    GUIDE_SECTION_PROGRESS = "The seven war fronts",
    GUIDE_PROGRESS_BODY = "Arathi Highlands, Loch Modan, Durotar, Ashenvale, Elwynn Forest and Redridge Mountains each have a capture path between two faction capitals. A point opens once the points before it are yours; several branches can be open at once. The special Hillsbrad front has only two large town circles: Southshore and Tarren Mill. It is a pure brawl: after a victory and its 15-minute truce, the fallen town comes back with no protection.\n\nOpen-world honorable kills at any level count once, from Blizzard's official counter.",
    GUIDE_SECTION_SHARD = "Layers and synchronization",
    GUIDE_SHARD_BODY = "Overlord shares captures and rankings with every player of your realm type (PvP, Normal, RP or Hardcore) through the addon channel, your group and Battle.net friends. Keep the addon up to date. The dot in the panel header shows the network health; /ov network gives details.\n\nA layer is the copy of the open world you are in. To fight beside allies on another layer, group with them or press the panel's Layer Jumper button: a volunteer on the other layer invites you and you switch within seconds, out of combat. Turn on Help others (/ov layer help on) to volunteer yourself.",
    GUIDE_SECTION_PANEL = "The Overlord panel",
    GUIDE_PANEL_BODY = "Open it with the minimap button or /ov show (/ov alone lists the commands). Choose a front to see its points, the current capture, recent fighting and the weekly domination bar. The panel's buttons open Call to arms, Command, Layer Jumper, the leaderboard and the Hall of Fame; your coins, Attack and Reinforce sit in the Next Objective card.\n\nTurn on Floating coins panel in Settings to also show them at the top of the screen near mines and keeps; /ov hud auto, on or off sets when they show. Reopen this guide from the panel or with /ov guide.",
    GUIDE_SECTION_OPTIONS = "Settings and commands",
    GUIDE_OPTIONS_BODY = "Settings in the panel, or Escape → Options → AddOns → Overlord: objective pin, map overlays, Minimap icons, sounds, panel scale and the floating panels. Handy commands: /ov lb (leaderboard), /ov map (map overlays), /ov sync (catch up), /ov wanted and /ov layer.",
    GUIDE_SECTION_CONTEST = "Capture and contest",
    GUIDE_CONTEST_BODY = "Stay 2 minutes in a normal circle; leaving makes the progress fall back. Enemies inside who match or outnumber you push it back, faster the more they outnumber you. A hostile capital takes 8 minutes; retaking your own takes 2.",
    GUIDE_SECTION_SIEGE = "Capital victory",
    GUIDE_SIEGE_BODY = "Once every other point of the front is yours, assault the enemy capital. Taking it wins the front: +1% weekly domination and a 15-minute truce.\n\nAfter the truce the conquest keeps your colours and the fallen capital rises again for its faction. It cannot be besieged for 6 hours, but its defenders may retake the whole front, your capital included, and win the front back.",
    GUIDE_SECTION_GOLD = "Coin mines",
    GUIDE_GOLD_BODY = "Mines on the map:\n%s\n\nInside a mine circle you gain 1 coin every 3 seconds (personal cap 100); mining an ore node gives 5. Spend 25 coins on an attack that shortens your next capture by 60 seconds, or a reinforcement that adds 60 seconds to the next enemy capture of one of your points (not capitals). The shared mine stock refills over time.",
    GUIDE_SECTION_FEATURED = "Featured front and weekly reset",
    GUIDE_FEATURED_BODY = "The featured front changes every day at midnight, your local time. Each official honorable kill on it gives +1 Overlord coin. Rankings, domination and the war map reset every Tuesday at 08:00 UTC.",
    GUIDE_SECTION_GUILD_KEEP = "Guild Keeps",
    GUIDE_GUILD_KEEP_BODY = "Five keeps stand in Stonetalon Mountains, Wetlands, Badlands, the Barrens and Mulgore.\n\nIcons: %s\n\nThey are open at all times. A guild member holds the square for %d minutes; leaving makes progress fall back, equal enemy numbers freeze it and more enemies push it back. Only the opposing faction can contest or take it. The keep stays with its guild until an enemy capture or the weekly reset; the leaderboard's keeps table counts their captures.",
    GUIDE_SECTION_OUTPOST = "Guild outposts",
    GUIDE_OUTPOST_BODY = "The six regular fronts have a guild outpost each; the two-point Southshore / Tarren Mill front has none. Savix Chapel in Silverpine Forest, Aeythyr Lodge in the Eastern Plaguelands and Lesi's Bear Cave in Darkshore are additional outposts. They follow the keep rules but take 5 minutes. While a guild of your faction holds a front's outpost, the enemy needs 30 more seconds to capture that front's ordinary points.",
    GUIDE_SECTION_FACTION_CALL = "Call to arms and General",
    GUIDE_FACTION_CALL_BODY = "On an active front, Call to arms sends a raid warning to every Overlord ally of your faction (once every 4 hours for the whole faction). A party or raid leader can press Command to become the faction's General: allies see them on the map and minimap and on their nameplate, and everyone is told when the General falls.",
    GUIDE_SECTION_ALERTS = "Alerts",
    GUIDE_ALERTS_BODY = "Most Wanted: the week's five best enemy killers carry a skull on their nameplate, and the chat warns you when one shows up (/ov wanted on or off). Overlord also warns you when an enemy guild racks up kills in a short time (/ov guildkills on or off).",
    GUIDE_SECTION_TOOLS = "Rankings and Hall of Fame",
    GUIDE_TOOLS_BODY = "The weekly leaderboard (/ov lb) lists honorable kills, guilds by kills, keeps and outposts, with a search box, the time left in the campaign and your own rank. /ov sync asks reachable players for a catch-up. The panel's Hall of Fame button shows last week's champions, your feats and the donors."
},
