de = {
    GUIDE_BTN_TOOLTIP = "Forever-Anleitung (3 Seiten)",
    GUIDE_PAGE1_TITLE = "Erste Schritte", GUIDE_PAGE2_TITLE = "Eroberung und Ressourcen",
    GUIDE_PAGE3_TITLE = "Festungen, Außenposten und Rangliste",
    GUIDE_SECTION_TRAVEL = "In die offene Welt",
    GUIDE_TRAVEL_ALLIANCE = "Reist zu einer Overlord-Front in der offenen Welt. Die Karte zeigt die Punkte, die ihr erobern könnt, und das nächste Ziel im Panel zeigt euch den Weg.",
    GUIDE_SECTION_RULES = "Vor der Eroberung",
    GUIDE_RULES_BODY = "Aktiviert PvP (/pvp) und bleibt zu Fuß im Kreis. Die Eroberung stoppt, solange ihr beritten seid, fliegt, in Reisegestalt, in einem Fahrzeug oder auf einer Flugroute unterwegs seid, verstohlen oder tot seid; wer in einen Kreis fliegt, wird nach einer kurzen Warnung abgesetzt.",
    GUIDE_SECTION_PROGRESS = "Die sieben Fronten",
    GUIDE_PROGRESS_BODY = "Arathihochland, Loch Modan, Durotar, Eschental, Wald von Elwynn und Rotkammgebirge haben je einen Eroberungsweg zwischen zwei Fraktionshauptstädten. Ein Punkt öffnet sich, sobald die Punkte davor euch gehören; mehrere Zweige können gleichzeitig offen sein. Die besondere Hügellandfront hat nur zwei große Ortskreise: Süderstade und Tarrens Mühle. Dort wird ununterbrochen gekämpft: Nach einem Sieg und 15 Minuten Waffenruhe kehrt die gefallene Stadt ohne Schutz zurück.\n\nEhrenhafte Siege in der offenen Welt zählen auf jeder Stufe einmal, nach Blizzards offiziellem Zähler.",
    GUIDE_SECTION_SHARD = "Layer und Synchronisierung",
    GUIDE_SHARD_BODY = "Overlord teilt Eroberungen und Ranglisten mit allen Spielern eures Realmtyps (PvP, Normal, RP oder Hardcore) über den Addon-Kanal, eure Gruppe und Battle.net-Freunde. Haltet das Addon aktuell. Der Punkt im Kopf des Panels zeigt den Zustand des Netzwerks; /ov network zeigt Details.\n\nEin Layer ist die Kopie der offenen Welt, in der ihr seid. Um mit Verbündeten auf einem anderen Layer zu kämpfen, bildet eine Gruppe mit ihnen oder nutzt die Schaltfläche Layer Jumper im Panel: Ein Freiwilliger auf dem anderen Layer lädt euch ein und ihr wechselt außerhalb des Kampfes in Sekunden. Schaltet Anderen helfen ein (/ov layer help on), um selbst zu helfen.",
    GUIDE_SECTION_PANEL = "Overlord-Panel",
    GUIDE_PANEL_BODY = "Öffnet es über die Minikarten-Schaltfläche oder mit /ov show (/ov allein listet die Befehle). Wählt eine Front, um ihre Punkte, die laufende Eroberung, jüngste Kämpfe und die wöchentliche Dominanzleiste zu sehen. Die Schaltflächen des Panels öffnen Kriegshorn, Kommando, Layer Jumper, die Rangliste und die Ruhmeshalle; eure Coins, Angriff und Verstärken stehen in der Karte des nächsten Ziels.\n\nAktiviert Schwebende Münzleiste in den Einstellungen, um sie auch oben am Bildschirm nahe Minen und Festungen zu sehen; /ov hud auto, on oder off legt fest, wann sie erscheinen. Öffnet diese Anleitung im Panel oder mit /ov guide erneut.",
    GUIDE_SECTION_OPTIONS = "Einstellungen und Befehle",
    GUIDE_OPTIONS_BODY = "Einstellungen im Panel oder in den Spieloptionen, Reiter AddOns → Overlord: Zielmarkierung, Kartenebenen, Minimap-Symbole, Töne, Panelgröße und schwebende Leisten. Nützliche Befehle: /ov lb (Rangliste), /ov map (Kartenebenen), /ov sync (aufholen), /ov wanted und /ov layer.",
    GUIDE_SECTION_CONTEST = "Eroberung und Gegenwehr",
    GUIDE_CONTEST_BODY = "Bleibt 2 Minuten in einem normalen Kreis; wer ihn verlässt, verliert Fortschritt. Gegner im Kreis, die euch ebenbürtig oder überlegen sind, drängen ihn zurück, umso schneller, je größer ihre Überzahl. Eine feindliche Hauptstadt braucht 8 Minuten, die eigene zurückzuerobern 2.",
    GUIDE_SECTION_SIEGE = "Sieg an der Hauptstadt",
    GUIDE_SIEGE_BODY = "Sobald alle anderen Punkte der Front euch gehören, greift die feindliche Hauptstadt an. Ihre Eroberung gewinnt die Front: +1 % Wochendominanz und 15 Minuten Waffenruhe.\n\nNach der Waffenruhe behält die Eroberung eure Farben und die gefallene Hauptstadt erhebt sich wieder für ihre Fraktion. Sie kann 6 Stunden lang nicht belagert werden, aber ihre Verteidiger dürfen die ganze Front zurückerobern, eure Hauptstadt eingeschlossen, und die Front zurückgewinnen.",
    GUIDE_SECTION_GOLD = "Coin-Minen",
    GUIDE_GOLD_BODY = "Minen auf der Karte:\n%s\n\nIm Kreis einer Mine gibt es alle 3 Sekunden 1 Coin (persönliches Maximum 100); ein Erzvorkommen gibt 5. Gebt 25 Coins für einen Angriff aus, der eure nächste Eroberung um 60 Sekunden verkürzt, oder für Verstärkung, die die nächste feindliche Eroberung eines eurer Punkte um 60 Sekunden verlängert (keine Hauptstädte). Der gemeinsame Vorrat füllt sich wieder auf.",
    GUIDE_SECTION_FEATURED = "Front des Tages und Wochenreset",
    GUIDE_FEATURED_BODY = "Die Front des Tages wechselt jeden Tag um Mitternacht nach eurer Ortszeit. Jeder offizielle ehrenhafte Sieg dort bringt +1 Overlord-Coin. Rangliste, Dominanz und Kriegskarte werden jeden Dienstag um 08:00 UTC zurückgesetzt.",
    GUIDE_SECTION_GUILD_KEEP = "Gildenfestungen",
    GUIDE_GUILD_KEEP_BODY = "Fünf Festungen stehen im Steinkrallengebirge, Sumpfland, Ödland, im Brachland und in Mulgore.\n\nSymbole: %s\n\nSie sind jederzeit offen. Ein Gildenmitglied hält das Quadrat %d Minuten; wer es verlässt, verliert Fortschritt, gleich viele Gegner stoppen ihn und mehr Gegner drängen ihn zurück. Nur die Gegenfraktion kann sie angreifen oder einnehmen. Die Festung bleibt bei ihrer Gilde bis zur feindlichen Eroberung oder zum Wochenreset; die Festungstabelle der Rangliste zählt ihre Eroberungen.",
    GUIDE_SECTION_OUTPOST = "Gilden-Außenposten",
    GUIDE_OUTPOST_BODY = "Die sechs regulären Fronten haben je einen Außenposten; die Front mit zwei Punkten Süderstade / Tarrens Mühle hat keinen. Die Kapelle von Savix im Silberwald, Aeythyrs Jagdhütte in den Östlichen Pestländern und Lesis Bärenhöhle an der Dunkelküste sind weitere Außenposten. Sie folgen den Festungsregeln, dauern aber 5 Minuten. Solange eine Gilde eurer Fraktion den Außenposten einer Front hält, braucht der Feind 30 Sekunden länger, um die normalen Punkte dieser Front zu erobern.",
    GUIDE_SECTION_FACTION_CALL = "Kriegshorn und General",
    GUIDE_FACTION_CALL_BODY = "An einer aktiven Front sendet das Kriegshorn eine Schlachtzugswarnung an alle Overlord-Verbündeten eurer Fraktion (einmal alle 4 Stunden für die ganze Fraktion). Ein Gruppen- oder Schlachtzugsleiter kann mit Kommando zum General seiner Fraktion werden: Verbündete sehen ihn auf Karte, Minikarte und Namensplakette, und alle erfahren es, wenn der General fällt.",
    GUIDE_SECTION_ALERTS = "Warnungen",
    GUIDE_ALERTS_BODY = "Most Wanted: Die fünf besten feindlichen Kämpfer der Woche tragen einen Totenkopf auf ihrer Namensplakette, und der Chat warnt euch, wenn einer auftaucht (/ov wanted on oder off). Overlord warnt euch auch, wenn eine feindliche Gilde in kurzer Zeit viele Siege einfährt (/ov guildkills on oder off).",
    GUIDE_SECTION_TOOLS = "Rangliste und Ruhmeshalle",
    GUIDE_TOOLS_BODY = "Die Wochenrangliste (/ov lb) zeigt ehrenhafte Siege, Gilden nach Siegen, Festungen und Außenposten, mit Suchfeld, der Restzeit der Kampagne und eurem eigenen Rang. /ov sync fordert Daten von erreichbaren Spielern an. Die Schaltfläche Ruhmeshalle im Panel zeigt die Champions der letzten Woche, eure Heldentaten und die Spender."
},
ru = {
    GUIDE_BTN_TOOLTIP = "Руководство Forever (3 страницы)",
    GUIDE_PAGE1_TITLE = "Первые шаги", GUIDE_PAGE2_TITLE = "Захват и ресурсы",
    GUIDE_PAGE3_TITLE = "Крепости, аванпосты и рейтинг",
    GUIDE_SECTION_TRAVEL = "Открытый мир",
    GUIDE_TRAVEL_ALLIANCE = "Отправляйтесь на фронт Overlord в открытом мире. Карта показывает точки, которые можно захватить, а следующая цель на панели подскажет, куда идти.",
    GUIDE_SECTION_RULES = "Перед захватом",
    GUIDE_RULES_BODY = "Включите режим PvP (/pvp) и стойте в круге пешком. Захват останавливается, если вы верхом, в полёте, в походном облике, в транспорте или на такси, под действием незаметности или мертвы; если влететь в круг, после короткого предупреждения вы будете спешены.",
    GUIDE_SECTION_PROGRESS = "Семь фронтов",
    GUIDE_PROGRESS_BODY = "Нагорье Арати, Лок Модан, Дуротар, Ясеневый лес, Элвиннский лес и Красногорье имеют цепочку захвата между двумя столицами фракций. Точка открывается, когда предыдущие точки ваши; несколько ветвей могут быть открыты одновременно. На особом фронте Хилсбрада только два больших круга: Южнобережье и Мельница Таррен. Там идёт непрерывная схватка: после победы и 15 минут перемирия павший город возвращается без защиты.\n\nПочётные победы в открытом мире засчитываются на любом уровне один раз, по официальному счётчику Blizzard.",
    GUIDE_SECTION_SHARD = "Слои и синхронизация",
    GUIDE_SHARD_BODY = "Overlord передаёт захваты и рейтинг всем игрокам вашего типа миров (PvP, обычный, RP или Hardcore) через канал аддона, вашу группу и друзей Battle.net. Обновляйте аддон. Точка в заголовке панели показывает состояние сети; подробности — /ov network.\n\nСлой (layer) — копия открытого мира, в которой вы находитесь. Чтобы сражаться рядом с союзниками на другом слое, вступите к ним в группу или нажмите кнопку Layer Jumper на панели: доброволец с другого слоя пригласит вас, и вне боя вы перейдёте за несколько секунд. Включите Помогать другим (/ov layer help on), чтобы стать добровольцем.",
    GUIDE_SECTION_PANEL = "Панель Overlord",
    GUIDE_PANEL_BODY = "Откройте её кнопкой у мини-карты или командой /ov show (/ov без параметров показывает список команд). Выберите фронт, чтобы увидеть его точки, текущий захват, недавние бои и полосу недельного господства. Кнопки панели открывают «К оружию», «Управление», Layer Jumper, рейтинг и Зал славы; ваши coins, «Атака» и «Укрепить» находятся в карточке следующей цели.\n\nВключите «Плавающая панель монет» в настройках, чтобы видеть их и вверху экрана рядом с рудниками и крепостями; /ov hud auto, on или off задаёт, когда она появляется. Руководство снова открывается из панели или командой /ov guide.",
    GUIDE_SECTION_OPTIONS = "Настройки и команды",
    GUIDE_OPTIONS_BODY = "Настройки в панели или в настройках игры, вкладка AddOns → Overlord: метка цели, слои карты, «Значки на мини-карте», звуки, масштаб панели и плавающие панели. Полезные команды: /ov lb (рейтинг), /ov map (слои карты), /ov sync (синхронизация), /ov wanted и /ov layer.",
    GUIDE_SECTION_CONTEST = "Захват и оспаривание",
    GUIDE_CONTEST_BODY = "Оставайтесь в обычном круге 2 минуты; если выйти, прогресс откатывается. Враги в круге, которых столько же или больше, чем вас, откатывают его тем быстрее, чем больше их перевес. Вражеская столица требует 8 минут, возврат своей — 2.",
    GUIDE_SECTION_SIEGE = "Победа у столицы",
    GUIDE_SIEGE_BODY = "Когда все остальные точки фронта ваши, штурмуйте вражескую столицу. Её захват приносит победу на фронте: +1 % недельного господства и 15 минут перемирия.\n\nПосле перемирия завоевания остаются в ваших цветах, а павшая столица восстаёт для своей фракции. Её нельзя осаждать 6 часов, но её защитники могут отвоевать весь фронт, включая вашу столицу, и вернуть себе победу.",
    GUIDE_SECTION_GOLD = "Рудники coins",
    GUIDE_GOLD_BODY = "Рудники на карте:\n%s\n\nВ круге рудника вы получаете 1 coin каждые 3 секунды (личный предел 100); добытая жила даёт 5. Потратьте 25 coins на «Атаку», которая сокращает ваш следующий захват на 60 секунд, или на «Укрепить», что продлевает следующий вражеский захват вашей точки на 60 секунд (кроме столиц). Общий запас рудника постепенно восстанавливается.",
    GUIDE_SECTION_FEATURED = "Фронт дня и недельный сброс",
    GUIDE_FEATURED_BODY = "Фронт дня меняется каждый день в полночь по времени вашего компьютера. Каждая официальная почётная победа на нём даёт +1 coin Overlord. Рейтинг, господство и карта войны сбрасываются каждый вторник в 08:00 UTC.",
    GUIDE_SECTION_GUILD_KEEP = "Гильдейские крепости",
    GUIDE_GUILD_KEEP_BODY = "Пять крепостей находятся в Когтистых горах, Болотине, Бесплодных землях, в Степях и в Мулгоре.\n\nЗначки: %s\n\nОни открыты в любое время. Член гильдии удерживает квадрат %d минут; при выходе прогресс откатывается, равное число врагов останавливает его, а превосходство откатывает. Оспорить или захватить крепость может только другая фракция. Крепость остаётся у гильдии до вражеского захвата или недельного сброса; таблица крепостей в рейтинге считает их захваты.",
    GUIDE_SECTION_OUTPOST = "Гильдейские аванпосты",
    GUIDE_OUTPOST_BODY = "У каждого из шести обычных фронтов есть аванпост; у фронта с двумя точками Южнобережье / Мельница Таррен его нет. Часовня Savix в Серебряном бору, Охотничий домик Aeythyr в Восточных Чумных землях и Медвежья пещера Lesi на Темных берегах — дополнительные аванпосты. Они подчиняются правилам крепостей, но захватываются за 5 минут. Пока гильдия вашей фракции держит аванпост фронта, враг захватывает обычные точки этого фронта на 30 секунд дольше.",
    GUIDE_SECTION_FACTION_CALL = "К оружию и Генерал",
    GUIDE_FACTION_CALL_BODY = "На активном фронте кнопка К оружию отправляет рейдовое предупреждение всем союзникам вашей фракции с Overlord (раз в 4 часа на всю фракцию). Лидер группы или рейда может нажать Управление и стать Генералом своей фракции: союзники видят его на карте, мини-карте и по табличке над головой, а о его гибели узнают все.",
    GUIDE_SECTION_ALERTS = "Оповещения",
    GUIDE_ALERTS_BODY = "Most Wanted: у пяти лучших вражеских бойцов недели над головой череп, а чат предупреждает, когда один из них появляется рядом (/ov wanted on или off). Overlord также предупреждает, когда вражеская гильдия быстро набирает победы (/ov guildkills on или off).",
    GUIDE_SECTION_TOOLS = "Рейтинг и Зал славы",
    GUIDE_TOOLS_BODY = "Недельный рейтинг (/ov lb) показывает почётные победы, гильдии по победам, крепости и аванпосты, с поиском, временем до конца кампании и вашим местом. /ov sync запрашивает данные у доступных игроков. Кнопка «Зал славы» на панели показывает чемпионов прошлой недели, ваши подвиги и имена тех, кто поддержал проект."
},
pt = {
    GUIDE_BTN_TOOLTIP = "Guia Forever (3 páginas)",
    GUIDE_PAGE1_TITLE = "Primeiros passos", GUIDE_PAGE2_TITLE = "Capturas e recursos",
    GUIDE_PAGE3_TITLE = "Fortalezas, postos e classificação",
    GUIDE_SECTION_TRAVEL = "Mundo aberto",
    GUIDE_TRAVEL_ALLIANCE = "Vá a uma frente do Overlord no mundo aberto. O mapa mostra os pontos que você pode capturar, e o Próximo objetivo do painel indica para onde ir.",
    GUIDE_SECTION_RULES = "Antes de capturar",
    GUIDE_RULES_BODY = "Ative o JxJ (/pvp) e fique a pé dentro do círculo. A captura para enquanto você estiver montado, voando, em forma de viagem, em um veículo ou táxi, furtivo ou morto; se entrar voando em um círculo, você desmonta após um breve aviso.",
    GUIDE_SECTION_PROGRESS = "As sete frentes",
    GUIDE_PROGRESS_BODY = "Planalto Arathi, Loch Modan, Durotar, Vale Gris, Floresta de Elwynn e Montanhas Cristarrubra têm uma rota de captura entre duas capitais de facção. Um ponto abre quando os pontos anteriores são seus; vários ramos podem estar abertos ao mesmo tempo. A frente especial de Eira dos Montes tem só dois círculos grandes: Costa Sul e Moinho Tarren. É uma briga sem pausa: depois de uma vitória e de 15 minutos de trégua, a cidade caída volta sem proteção.\n\nAbates honrosos no mundo aberto contam uma vez, em qualquer nível, pelo contador oficial da Blizzard.",
    GUIDE_SECTION_SHARD = "Layers e sincronização",
    GUIDE_SHARD_BODY = "O Overlord compartilha capturas e classificações com todos os jogadores do seu tipo de reino (JxJ, Normal, RP ou Hardcore) pelo canal do addon, seu grupo e amigos da Battle.net. Mantenha o addon atualizado. O ponto no cabeçalho do painel mostra o estado da rede; /ov network dá os detalhes.\n\nUm layer é a cópia do mundo aberto em que você está. Para lutar ao lado de aliados em outro layer, forme grupo com eles ou use o botão Layer Jumper do painel: um voluntário do outro layer convida você e a troca leva segundos, fora de combate. Ative Ajudar os outros (/ov layer help on) para ser voluntário.",
    GUIDE_SECTION_PANEL = "Painel do Overlord",
    GUIDE_PANEL_BODY = "Abra pelo botão do minimapa ou com /ov show (/ov sozinho lista os comandos). Escolha uma frente para ver seus pontos, a captura em andamento, os combates recentes e a barra de dominação semanal. Os botões do painel abrem Chamado às armas, Comando, Layer Jumper, a classificação e o Hall da Fama; suas coins, Ataque e Reforçar ficam no cartão Próximo objetivo.\n\nAtive Painel de moedas flutuante nas Configurações para vê-los também no alto da tela, perto das minas e fortalezas; /ov hud auto, on ou off define quando aparecem. Reabra este guia pelo painel ou com /ov guide.",
    GUIDE_SECTION_OPTIONS = "Configurações e comandos",
    GUIDE_OPTIONS_BODY = "Configurações no painel, ou nas opções do jogo, aba AddOns → Overlord: marcador do objetivo, camadas do mapa, Ícones do minimapa, sons, escala do painel e painéis flutuantes. Comandos úteis: /ov lb (classificação), /ov map (camadas do mapa), /ov sync (sincronizar), /ov wanted e /ov layer.",
    GUIDE_SECTION_CONTEST = "Captura e disputa",
    GUIDE_CONTEST_BODY = "Fique 2 minutos em um círculo comum; ao sair, o progresso volta. Inimigos dentro que igualam ou superam seu número o fazem recuar, mais rápido quanto maior a vantagem deles. Uma capital inimiga leva 8 minutos; retomar a sua leva 2.",
    GUIDE_SECTION_SIEGE = "Vitória na capital",
    GUIDE_SIEGE_BODY = "Quando todos os outros pontos da frente forem seus, ataque a capital inimiga. Tomá-la vence a frente: +1% de dominação semanal e 15 minutos de trégua.\n\nApós a trégua, a conquista mantém suas cores e a capital caída se reergue para sua facção. Ela não pode ser sitiada por 6 horas, mas seus defensores podem retomar toda a frente, incluindo a sua capital, e reconquistar a vitória.",
    GUIDE_SECTION_GOLD = "Minas de coins",
    GUIDE_GOLD_BODY = "Minas no mapa:\n%s\n\nDentro do círculo de uma mina, você ganha 1 coin a cada 3 segundos (limite pessoal 100); minerar uma jazida dá 5. Gaste 25 coins em um ataque que encurta sua próxima captura em 60 segundos, ou em um reforço que soma 60 segundos à próxima captura inimiga de um dos seus pontos (exceto capitais). O estoque compartilhado se recompõe com o tempo.",
    GUIDE_SECTION_FEATURED = "Frente do dia e reinício semanal",
    GUIDE_FEATURED_BODY = "A frente do dia muda todos os dias à meia-noite, no horário do seu computador. Cada abate honroso oficial nela dá +1 coin Overlord. A classificação, a dominação e o mapa de guerra reiniciam toda terça-feira às 08:00 UTC.",
    GUIDE_SECTION_GUILD_KEEP = "Fortalezas de guilda",
    GUIDE_GUILD_KEEP_BODY = "Há cinco fortalezas na Serra das Torres de Pedra, Pantanal, Ermos, Sertões e Mulgore.\n\nÍcones: %s\n\nElas ficam abertas a qualquer hora. Um membro da guilda segura o quadrado por %d minutos; sair reduz o progresso, inimigos em número igual o congelam e em maioria o fazem recuar. Só a facção adversária pode disputar ou tomar. A fortaleza fica com sua guilda até uma captura inimiga ou o reinício semanal; a tabela de fortalezas da classificação conta suas capturas.",
    GUIDE_SECTION_OUTPOST = "Postos avançados de guilda",
    GUIDE_OUTPOST_BODY = "Cada uma das seis frentes comuns tem um posto avançado; a frente de dois pontos Costa Sul / Moinho Tarren não tem. A Capela Savix na Floresta de Pinhaprata, o Pavilhão de Aeythyr nas Terras Pestilentas Orientais e a Caverna do Urso de Lesi na Costa Negra são postos adicionais. Eles seguem as regras das fortalezas, mas levam 5 minutos. Enquanto uma guilda da sua facção tiver o posto de uma frente, o inimigo precisa de 30 segundos a mais para capturar os pontos comuns dessa frente.",
    GUIDE_SECTION_FACTION_CALL = "Chamado às armas e General",
    GUIDE_FACTION_CALL_BODY = "Em uma frente ativa, o Chamado às armas envia um aviso de raide a todos os aliados Overlord da sua facção (uma vez a cada 4 horas para toda a facção). Um líder de grupo ou raide pode clicar em Comando para ser o General da sua facção: os aliados o veem no mapa, no minimapa e na placa de nome, e todos são avisados quando o General cai.",
    GUIDE_SECTION_ALERTS = "Alertas",
    GUIDE_ALERTS_BODY = "Most Wanted: os cinco melhores matadores inimigos da semana têm uma caveira na placa de nome, e o chat avisa quando um deles aparece (/ov wanted on ou off). O Overlord também avisa quando uma guilda inimiga acumula abates em pouco tempo (/ov guildkills on ou off).",
    GUIDE_SECTION_TOOLS = "Classificação e Hall da Fama",
    GUIDE_TOOLS_BODY = "A classificação semanal (/ov lb) mostra abates honrosos, guildas por abates, fortalezas e postos, com busca, o tempo restante da campanha e a sua posição. /ov sync pede dados aos jogadores alcançáveis. O botão Hall da Fama do painel mostra os campeões da semana passada, seus feitos e os doadores."
},
zhCN = {
    GUIDE_BTN_TOOLTIP = "Forever 指南（3 页）",
    GUIDE_PAGE1_TITLE = "入门", GUIDE_PAGE2_TITLE = "占领与资源",
    GUIDE_PAGE3_TITLE = "公会要塞、前哨与排行",
    GUIDE_SECTION_TRAVEL = "前往开放世界",
    GUIDE_TRAVEL_ALLIANCE = "前往开放世界中的 Overlord 战线。地图会显示你可以占领的据点，面板中的“下一个目标”会告诉你该去哪里。",
    GUIDE_SECTION_RULES = "占领之前",
    GUIDE_RULES_BODY = "开启 PvP（/pvp），并徒步站在占领圈内。骑乘、飞行、旅行形态、载具或飞行路线中、潜行或死亡时，占领都会停止；飞入占领圈时，短暂警告后会自动下坐骑。",
    GUIDE_SECTION_PROGRESS = "七条战线",
    GUIDE_PROGRESS_BODY = "阿拉希高地、洛克莫丹、杜隆塔尔、灰谷、艾尔文森林和赤脊山各有一条连接双方阵营首都的占领路线。之前的据点都归你后，下一个据点才会开放；多条分支可同时开放。希尔斯布莱德特殊战线只有两个大范围据点：南海镇和塔伦米尔。那里是持续的混战：胜利及 15 分钟停战之后，陷落的城镇会归还其阵营，但不受保护。\n\n任何等级在开放世界获得的荣誉击杀，都按暴雪官方计数器只计一次。",
    GUIDE_SECTION_SHARD = "Layer 与同步",
